const crypto = require('node:crypto')
const { readJsonBody, replyJson: reply, sameOrigin } = require('./panel-http')

const FEEDBACK_HEARTBEAT_MS = 20000

function createGateway ({
  username,
  password,
  room = 'room-01',
  onBoundCommand,
  onBoundLogin,
  onAuthenticatedRequest,
  onSessionClosed,
  holdEpoch,
  secureCookie = false,
  prefix,
  sessionTtlMs = 8 * 3600000,
  restoredSessions
}) {
  const routePrefix = prefix
  if (typeof prefix !== 'string' || !/^\/control-panel-api\/panels\/[A-Za-z0-9._-]+$/.test(prefix)) {
    throw Error('A panel-scoped API prefix is required')
  }
  if (!username || typeof password !== 'string' || password.length < 12) {
    throw Error('Set a username and password of at least 12 characters')
  }
  if (!Number.isSafeInteger(sessionTtlMs) || sessionTtlMs < 1) {
    throw Error('Invalid session lifetime')
  }

  const salt = crypto.randomBytes(16)
  const hash = crypto.scryptSync(password, salt, 32)
  const sessions = new Map()
  if (restoredSessions instanceof Map) {
    for (const [token, session] of restoredSessions) {
      if (sessions.size >= 100) break
      if (typeof token === 'string' && typeof session?.csrf === 'string' &&
        Number.isFinite(session.expiry) && session.expiry > Date.now()) {
        sessions.set(token, { csrf: session.csrf, expiry: session.expiry })
      }
    }
  }
  const attempts = new Map()
  const subscribers = new Set()
  const boundState = new Map()
  const feedbackEpoch = crypto.randomBytes(16).toString('hex')
  let boundRevision = 0
  let closed = false
  let heartbeatTimer = null

  function closeSubscriber (subscriber, destroy = false) {
    if (!subscribers.delete(subscriber)) return
    try { if (destroy) subscriber.res.destroy(); else subscriber.res.end() } catch (_) {}
    if (!subscribers.size && heartbeatTimer) {
      clearInterval(heartbeatTimer)
      heartbeatTimer = null
    }
  }

  function writeSubscriber (subscriber, data) {
    try {
      // Allow one queued write to drain, including a large initial snapshot.
      // A persistently blocked client reconnects to the latest snapshot.
      if (subscriber.blocked) return closeSubscriber(subscriber, true)
      if (subscriber.res.write(data) === false) subscriber.blocked = true
    } catch (_) { closeSubscriber(subscriber, true) }
  }

  function ensureHeartbeat () {
    if (heartbeatTimer || !subscribers.size) return
    heartbeatTimer = setInterval(() => {
      const now = Date.now()
      for (const subscriber of [...subscribers]) {
        const session = sessions.get(subscriber.token)
        if (!session || session.expiry < now) {
          sessions.delete(subscriber.token)
          onSessionClosed?.(subscriber.token)
          closeSubscriber(subscriber)
          continue
        }
        writeSubscriber(subscriber, ': heartbeat\n\n')
      }
    }, FEEDBACK_HEARTBEAT_MS)
    heartbeatTimer.unref?.()
  }

  function sendFeedbackEvent (subscriber, message) {
    writeSubscriber(subscriber, 'data: ' + JSON.stringify(message) + '\n\n')
  }


  function broadcastFeedback (message) {
    if (!subscribers.size) return
    const data = 'data: ' + JSON.stringify(message) + '\n\n'
    for (const subscriber of [...subscribers]) writeSubscriber(subscriber, data)
  }

  function closeSubscribersForToken (token) {
    for (const subscriber of [...subscribers]) {
      if (subscriber.token === token) closeSubscriber(subscriber)
    }
  }


  function boundFeedback (items) {
    if (!Array.isArray(items) || !items.length ||
      items.some(item => !item || typeof item.id !== 'string' || !item.id ||
        !Object.hasOwn(item, 'value'))) {
      throw Error('Invalid bound feedback')
    }
    for (const { id, value } of items) boundState.set(id, value)
    boundRevision++
    const message = { room, kind: 'bound-feedback', items, revision: boundRevision, feedbackEpoch }
    broadcastFeedback(message)
    return message
  }

  let availability = []
  function boundAvailability (items) {
    if (!Array.isArray(items) || items.some(item => typeof item?.id !== 'string' || typeof item.available !== 'boolean')) {
      throw Error('Invalid bound availability')
    }
    availability = items.map(item => ({ id: item.id, available: item.available }))
    boundRevision++
    broadcastFeedback({ room, kind: 'bound-availability', availability, revision: boundRevision, feedbackEpoch })
  }

  function boundSnapshot () {
    return {
      room, kind: 'bound-snapshot', feedbackEpoch,
      items: [...boundState].map(([id, value]) => ({ id, value })),
      revision: boundRevision,
      ...(availability.length ? { availability } : {})
    }
  }

  const cookieName = 'room_panel_' + Buffer.from(room).toString('hex')
  const cookie = (token, maxAge, req) => `${cookieName}=${token}; Path=${routePrefix}; HttpOnly; SameSite=Strict; Max-Age=${maxAge}${req.socket.encrypted ? '; Secure' : ''}`

  async function handler (req, res) {
    const path = new URL(req.url, 'http://localhost').pathname
    if (!path.startsWith(routePrefix + '/')) return false
    if (closed) {
      reply(res, 503, { error: 'Gateway unavailable' })
      return true
    }

    try {
      const now = Date.now()
      for (const [id, session] of sessions) {
        if (session.expiry < now) {
          sessions.delete(id)
          onSessionClosed?.(id)
          closeSubscribersForToken(id)
        }
      }
      for (const [ip, attempt] of attempts) if (attempt.until < now) attempts.delete(ip)

      if (req.method === 'POST') {
        if (!sameOrigin(req)) {
          reply(res, 403, { error: 'Origin rejected' })
          return true
        }
      }

      if (path === routePrefix + '/login' && req.method === 'POST') {
        const ip = req.socket.remoteAddress || 'unknown'
        const entry = attempts.get(ip) || { count: 0, until: now + 60000 }
        if (entry.count >= 10 || attempts.size > 1000) {
          reply(res, 429, { error: 'Too many attempts. Wait one minute.' })
          return true
        }
        entry.count++
        attempts.set(ip, entry)
        const data = await readJsonBody(req, 8192)
        const supplied = String(data.password || '')
        if (supplied.length > 256) {
          reply(res, 401, { error: 'Invalid credentials' })
          return true
        }
        const test = await new Promise((resolve, reject) => {
          crypto.scrypt(supplied, salt, 32, (error, key) => error ? reject(error) : resolve(key))
        })
        const passwordMatch = crypto.timingSafeEqual(test, hash)
        const usernameMatch = data.username === username
        if (!passwordMatch || !usernameMatch) {
          reply(res, 401, { error: 'Invalid credentials' })
          return true
        }
        if (sessions.size >= 100) {
          reply(res, 503, { error: 'Session limit reached' })
          return true
        }
        attempts.delete(ip)
        const token = crypto.randomBytes(32).toString('hex')
        const csrf = crypto.randomBytes(24).toString('hex')
        sessions.set(token, { csrf, expiry: now + sessionTtlMs })
        reply(res, 200, { room, username, csrf, feedbackEpoch, ...(holdEpoch ? { holdEpoch } : {}) }, {
          'Set-Cookie': cookie(token, Math.ceil(sessionTtlMs / 1000), req)
        })
        if (typeof onBoundLogin === 'function') {
          queueMicrotask(() => { if (!closed) onBoundLogin({ room, user: username }) })
        }
        return true
      }

      const token = String(req.headers.cookie || '').split(';')
        .map(value => value.trim())
        .find(value => value.startsWith(cookieName + '='))
        ?.split('=')[1]
      const session = sessions.get(token)
      if (!session) {
        reply(res, 401, { error: 'Login required' })
        return true
      }
      if (req.method === 'POST' && req.headers['x-room-csrf'] !== session.csrf) {
        reply(res, 403, { error: 'CSRF rejected' })
        return true
      }
      if (onAuthenticatedRequest && await onAuthenticatedRequest(req, res,
        { token, expiry: session.expiry, room, user: username })) return true
      if (path === routePrefix + '/session' && req.method === 'GET') {
        reply(res, 200, { room, username, csrf: session.csrf, feedbackEpoch, ...(holdEpoch ? { holdEpoch } : {}) })
        onBoundLogin?.({ room, user: username })
        return true
      }
      if (path === routePrefix + '/events' && req.method === 'GET') {
        if (subscribers.size >= 100) {
          reply(res, 503, { error: 'Feedback connection limit reached' })
          return true
        }
        res.writeHead(200, {
          'Content-Type': 'text/event-stream; charset=utf-8',
          'Cache-Control': 'no-cache, no-transform',
          Connection: 'keep-alive',
          'X-Accel-Buffering': 'no',
          'X-Content-Type-Options': 'nosniff'
        })
        res.flushHeaders?.()
        const subscriber = { res, token, blocked: false }
        subscribers.add(subscriber)
        res.on('drain', () => { subscriber.blocked = false })
        res.on('close', () => closeSubscriber(subscriber))
        sendFeedbackEvent(subscriber, boundSnapshot())
        onBoundLogin?.({ room, user: username })
        ensureHeartbeat()
        return true
      }
      if (path === routePrefix + '/state' && req.method === 'GET') {
        if (new URL(req.url, 'http://localhost').searchParams.get('room') !== room) {
          reply(res, 403, { error: 'Region denied' })
          return true
        }
        reply(res, 200, boundSnapshot())
        return true
      }
      if (path === routePrefix + '/logout' && req.method === 'POST') {
        sessions.delete(token)
        onSessionClosed?.(token)
        closeSubscribersForToken(token)
        reply(res, 200, { ok: true }, { 'Set-Cookie': cookie('', 0, req) })
        return true
      }
      if (path === routePrefix + '/bound-command' && req.method === 'POST') {
        if (typeof onBoundCommand !== 'function') {
          reply(res, 404, { error: 'Not found' })
          return true
        }
        // A valid 4096-character text value can occupy more than 8 KiB in
        // UTF-8 or JSON escapes. Keep a bounded envelope above that limit.
        const data = await readJsonBody(req, 32768)
        if (data.room !== room) {
          reply(res, 403, { error: 'Region denied' })
          return true
        }
        const result = await onBoundCommand(data, { room, user: username, token, expiry: session.expiry })
        if (result === false) {
          reply(res, 409, { error: 'Managed bridge is out of sync' })
          return true
        }
        reply(res, 200, { ok: true, ...(typeof result?.held === 'boolean' ? { held: result.held } : {}) })
        return true
      }

      reply(res, 404, { error: 'Not found' })
    } catch (error) {
      reply(res, 400, { error: 'Invalid request' })
    }
    return true
  }

  return {
    handler,
    boundFeedback,
    boundAvailability,
    sessionActive: token => !closed && (sessions.get(token)?.expiry || 0) > Date.now(),
    sessionSnapshot () {
      return new Map([...sessions].filter(([, session]) => session.expiry > Date.now())
        .map(([token, session]) => [token, { ...session }]))
    },
    close () {
      closed = true
      for (const subscriber of [...subscribers]) closeSubscriber(subscriber)
      if (heartbeatTimer) clearInterval(heartbeatTimer)
      heartbeatTimer = null
      sessions.clear()
      attempts.clear()
    }
  }
}

module.exports = { createGateway }
